INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Netzwerkmodell immer nur eine Schicht hat?', 2, '[{"text": "Nein", "correct": true, "because": "Sieben Schichten vorhanden"}, {"text": "Ja", "correct": false, "because": "Mehrschichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schicht ist für die physische Verbindung zuständig?', 3, '[{"text": "Schicht 1", "correct": true, "because": "Physikalische Schicht"}, {"text": "Schicht 3", "correct": false, "because": "Netzwerkschicht"}, {"text": "Schicht 7", "correct": false, "because": "Anwendungsschicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schichten gehören zu diesem Modell?', 5, '[{"text": "Physikalisch", "correct": true, "because": "Schicht 1"}, {"text": "Sicherung", "correct": true, "because": "Schicht 2"}, {"text": "Anwendung", "correct": true, "because": "Schicht 7"}, {"text": "Design", "correct": false, "because": "Kein Teil"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schicht 3 leitet Datenpakete. b) Schicht 7 ist für Hardware.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 7 ist Anwendung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich ein Netzwerk analysiere?', 4, '[{"text": "Schicht 2", "correct": false, "because": "Sicherung wichtig"}, {"text": "Schicht 4", "correct": false, "because": "Transport entscheidend"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Modell nur für Hardware ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Software-Schichten"}, {"text": "Ja", "correct": false, "because": "Umfassend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schicht verantwortet die Datenübertragung zwischen Netzwerken?', 3, '[{"text": "Schicht 3", "correct": true, "because": "Netzwerkschicht"}, {"text": "Schicht 1", "correct": false, "because": "Physikalisch"}, {"text": "Schicht 5", "correct": false, "because": "Sitzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet dieses Modell?', 5, '[{"text": "Struktur", "correct": true, "because": "Klarer Aufbau"}, {"text": "Standardisierung", "correct": true, "because": "Protokolle einheitlich"}, {"text": "Fehleranalyse", "correct": true, "because": "Schichten isolierbar"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Schicht 4 für Transport ist und b) Schicht 2 für Routing. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 2 ist Sicherung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um das Modell zu verstehen?', 4, '[{"text": "Schichtaufbau", "correct": false, "because": "Grundlage"}, {"text": "Protokolle", "correct": false, "because": "Funktion definieren"}, {"text": "Büroverschönerung", "correct": true, "because": "Kein technischer Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Schicht 7 für physikalische Verbindungen?', 2, '[{"text": "Nein", "correct": true, "because": "Das ist Schicht 1"}, {"text": "Ja", "correct": false, "because": "Schicht 7 ist Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schichten arbeiten mit Protokollen wie TCP?', 4, '[{"text": "Schicht 4", "correct": true, "because": "Transport"}, {"text": "Schicht 3", "correct": true, "because": "Netzwerk mit IP"}, {"text": "Schicht 1", "correct": false, "because": "Nur physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Modell nur theoretisch ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Praktisch anwendbar"}, {"text": "Ja", "correct": false, "because": "Basis für Protokolle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit diesem Modell?', 3, '[{"text": "Netzwerkkommunikation", "correct": true, "because": "Strukturiert Abläufe"}, {"text": "Datenkompression", "correct": false, "because": "Anderer Zweck"}, {"text": "Designverbesserung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Schicht 2 sichert Datenrahmen. b) Schicht 5 leitet Pakete.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schicht 5 ist Sitzung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt Schicht 4?', 4, '[{"text": "Transport", "correct": true, "because": "Verwaltet Datenfluss"}, {"text": "Routing", "correct": false, "because": "Schicht 3"}, {"text": "Design", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob HTTP auf Schicht 7 läuft?', 2, '[{"text": "Ja", "correct": true, "because": "Anwendungsschicht"}, {"text": "Nein", "correct": false, "because": "Korrekte Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren machen das Modell nützlich?', 5, '[{"text": "Schichtung", "correct": true, "because": "Klarer Aufbau"}, {"text": "Protokollzuordnung", "correct": true, "because": "Definiert Funktionen"}, {"text": "Fehlerisolierung", "correct": true, "because": "Schichten trennen"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Schicht 1 für IP-Adressen?', 3, '[{"text": "Nein", "correct": true, "because": "Schicht 3"}, {"text": "Ja", "correct": false, "because": "Schicht 1 ist physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Szenario passt zu Schicht 2?', 4, '[{"text": "Switching in einem LAN", "correct": true, "because": "Sicherungsschicht"}, {"text": "Routing zwischen Netzen", "correct": false, "because": "Schicht 3"}, {"text": "Webseitenanzeige", "correct": false, "because": "Schicht 7"}]');
